<script setup lang="ts">
import {computed,ref} from 'vue';
import {elementPalette} from '../styles/palette';
import LibraryToolbar from './LibraryToolbar.vue';
import LibraryShortcuts from './LibraryShortcuts.vue';
import WorkbenchDialog from './WorkbenchDialog.vue';
import SortPanel from './SortPanel.vue';
import FilterActions from './FilterActions.vue';
import GameIcon from './GameIcon.vue';
const props=withDefaults(defineProps<{query:string;elements:string[];weapons:string[];rarities:string[];favorites?:string[];sort:string;direction:'asc'|'desc';label:string;sortOptions:{value:string;label:string}[]}>(),{});
const emit=defineEmits<{'update:query':[value:string];'update:elements':[value:string[]];'update:weapons':[value:string[]];'update:rarities':[value:string[]];'update:favorites':[value:string[]];'update:sort':[value:string];'update:direction':[value:'asc'|'desc']}>();
const filterOpen=ref(false),sortOpen=ref(false);
type Group='elements'|'weapons'|'rarities'|'favorites';
function set(id:Group,value:string[]){if(id==='elements')emit('update:elements',value);else if(id==='weapons')emit('update:weapons',value);else if(id==='rarities')emit('update:rarities',value);else emit('update:favorites',value);}
function clear(){set('elements',[]);set('weapons',[]);set('rarities',[]);if(props.favorites)set('favorites',[]);}
const count=computed(()=>props.elements.length+props.weapons.length+props.rarities.length+(props.favorites?.length ?? 0));
const groups=computed<{id:Group;title:string;selected:string[];options:{id:string;name:string;icon?:string}[]}[]>(()=>[
  {id:'elements',title:'元素',selected:props.elements,options:elementPalette.map(item=>({id:item.id,name:item.name}))},
  ...(props.favorites?[{id:'favorites' as const,title:'收藏',selected:props.favorites,options:[{id:'0',name:'未收藏'},{id:'1',name:'1级收藏'},{id:'2',name:'2级收藏'},{id:'3',name:'3级收藏'}]}]:[]),
  {id:'rarities',title:'星级',selected:props.rarities,options:[{id:'4',name:'四星'},{id:'5',name:'五星'}]},
  {id:'weapons',title:'武器类型',selected:props.weapons,options:[{id:'WEAPON_SWORD_ONE_HAND',name:'单手剑',icon:'dullblade'},{id:'WEAPON_CLAYMORE',name:'双手剑',icon:'wastergreatsword'},{id:'WEAPON_POLE',name:'长柄武器',icon:'beginnersprotector'},{id:'WEAPON_BOW',name:'弓',icon:'huntersbow'},{id:'WEAPON_CATALYST',name:'法器',icon:'apprenticesnotes'}]},
]);
function sortKey(value:string){emit('update:sort',value);emit('update:direction',value==='name'?'asc':'desc');}
function resetSort(){emit('update:sort','release');emit('update:direction','desc');}
</script>
<template><div class="character-library-tools"><LibraryToolbar :model-value="query" :label="label" placeholder="查找角色…" :filter-count="count" :sorted="sort!=='release' || direction!=='desc'" @update:model-value="emit('update:query',$event)" @filter="filterOpen=true" @sort="sortOpen=true" @reset="clear();resetSort()"><template v-if="$slots.actions" #actions><slot name="actions" /></template></LibraryToolbar><div class="character-shortcut-row"><LibraryShortcuts :model-value="elements" label="按元素筛选" all-label="全部" kind="elements" :mobile-columns="4" :options="elementPalette.map(item=>({value:item.id,label:item.name,light:item.light,deep:item.deep}))" @update:model-value="set('elements',$event)" /></div><WorkbenchDialog v-if="filterOpen" title="筛选角色" size="filter" @close="filterOpen=false"><div class="character-filter-panel"><section v-for="group in groups" :key="group.id" :aria-label="group.title"><h3>{{ group.title }}</h3><div class="filter-options"><button :aria-pressed="!group.selected.length" @click="set(group.id,[])">全部</button><button v-for="item in group.options" :key="item.id" :aria-pressed="group.selected.includes(item.id)" @click="set(group.id,group.selected.includes(item.id)?group.selected.filter(value=>value!==item.id):[...group.selected,item.id])"><GameIcon v-if="group.id==='elements'" kind="elements" :id="item.id" :size="24" /><GameIcon v-else-if="group.id==='weapons'" kind="weapons" :id="item.icon" :size="24" /><svg v-else viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/></svg>{{ item.name }}</button></div></section></div><template #footer><FilterActions flush @reset="clear" @confirm="filterOpen=false" /></template></WorkbenchDialog><WorkbenchDialog v-if="sortOpen" title="角色排序" size="filter" @close="sortOpen=false"><SortPanel :model-value="sort" :direction="direction" :options="sortOptions" @update:model-value="sortKey" @update:direction="emit('update:direction',$event)" @reset="resetSort" @confirm="sortOpen=false" /></WorkbenchDialog></div></template>
<style scoped>.character-library-tools { display:contents; }.character-shortcut-row { margin:12px 0; }.character-filter-panel { display:grid; gap:20px; }.character-filter-panel h3 { font-size:var(--font-control); margin:0 0 10px; }.filter-options { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:8px; }.filter-options button { display:flex; align-items:center; justify-content:center; gap:5px; min-width:0; height:40px; padding:0 6px; font-size:var(--font-control); font-weight:700; }.filter-options svg { width:18px; height:18px; color:var(--element-geo-deep); }.filter-options button[aria-pressed=true] { background:var(--element-anemo-light); border-color:var(--element-anemo-primary); color:var(--element-anemo-deep); }@media(max-width:500px) { .filter-options { grid-template-columns:repeat(2,minmax(0,1fr)); } }</style>
